  "api.errors.auth.resetEmailUnavailable": "\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0639\u064A\u064A\u0646 \u0628\u0627\u0644\u0628\u0631\u064A\u062F \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629 \u062D\u0627\u0644\u064A\u0627\u064B. \u0627\u0633\u062A\u062E\u062F\u0645 \u0648\u0627\u062A\u0633\u0627\u0628 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0631\u0642\u0645\u0643 \u0645\u0635\u0631\u064A\u0627\u064B.",
